INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孔纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：孔纬。", "biography": null, "status": "draft", "id": "07254f47-15dc-55d0-b38f-bfefa4def94e"}, {"name": "张浚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张浚。", "biography": null, "status": "draft", "id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "崔昭纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：崔昭纬。", "biography": null, "status": "draft", "id": "99370461-a1dd-57da-a64e-c76fb6ea7ba7"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "王行瑜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王行瑜。", "biography": null, "status": "draft", "id": "65e50f4b-8971-5070-b043-77c6748c1fc0"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "韩建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“韩建出任司徒、同平章事”中为受任者。", "biography": null, "status": "draft", "id": "0a022fc7-47b3-5530-98ad-3625fceab9a5"}, {"name": "王瑶", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：王瑶。", "biography": null, "status": "draft", "id": "8a33b361-edde-5e3a-a60d-fd38c8d61355"}, {"name": "王珂", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：王珂。", "biography": null, "status": "draft", "id": "d1dd3473-2a2a-5fe6-83c7-7b57a585471c"}, {"name": "王行约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：王行约。", "biography": null, "status": "draft", "id": "e3ef8c5d-f45c-5024-998e-2dd76a19b8ae"}, {"name": "王行实", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：王行实。", "biography": null, "status": "draft", "id": "ad52d1af-989c-586b-8175-cb1e02d91987"}, {"name": "骆全瓘", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：骆全瓘。", "biography": null, "status": "draft", "id": "9581858b-fa64-5be6-a44e-6a4bc86f42c4"}, {"name": "李继鹏", "aliases": ["阎珪"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李继鹏。", "biography": null, "status": "draft", "id": "e895a8b1-ba20-54af-a4c3-05706851982d"}, {"name": "刘景宣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：刘景宣。", "biography": null, "status": "draft", "id": "4588bc93-43ed-56e6-83f4-dd2d74462ad9"}, {"name": "李筠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李筠。", "biography": null, "status": "draft", "id": "857ef869-72e5-53c2-a513-a31d4475201b"}, {"name": "李居实", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李居实。", "biography": null, "status": "draft", "id": "b1a198c2-4b88-568e-ad94-3669729ae95e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "孔纬张浚授太子宾客", "start_year": 895, "end_year": 895, "time_original": "895年六月辛卯", "dynasty": "唐", "description": "朝廷以前均州刺史孔纬、绣州司户张浚为太子宾客。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d94f6681-af9e-539c-afb4-cd235b954db8"}, {"title": "孔纬授吏部尚书，恢复阶爵", "start_year": 895, "end_year": 895, "time_original": "895年六月壬辰", "dynasty": "唐", "description": "孔纬授吏部尚书，恢复其阶爵。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "17d4bc2f-95a7-5d7b-9f80-ab3f1bb23d66"}, {"title": "孔纬授司空兼门下侍郎同平章事", "start_year": 895, "end_year": 895, "time_original": "895年六月癸已；底本日字如此", "dynasty": "唐", "description": "孔纬授司空，兼门下侍郎、同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6bac711c-ccdd-511e-a032-a760459fed7e"}, {"title": "张浚授兵部尚书诸道租庸使", "start_year": 895, "end_year": 895, "time_original": "895年六月复用条；确日未另载", "dynasty": "唐", "description": "张浚授兵部尚书、诸道租庸使。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6d27f4ed-f56a-5040-aa4d-317d7e9eb23d"}, {"title": "唐昭宗因朋党倾轧而骤用孔纬张浚", "start_year": 895, "end_year": 895, "time_original": "895年六月再用时", "dynasty": "唐", "description": "孔纬时居华州，张浚居长水。唐昭宗因崔昭纬等外结藩镇、朋党相倾，想用骨鲠之士，迅速复用二人。", "phases": [], "location_name": "华州、长水、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "483f2d85-43c6-56e6-8a54-14c0fcd788af"}, {"title": "孔纬患病扶舆入京，辞命未许", "start_year": 895, "end_year": 895, "time_original": "895年六月受命后；确日未载", "dynasty": "唐", "description": "孔纬有病，扶舆到京师见皇帝，涕泣固辞，皇帝不许。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4c55cd9c-12bd-5f96-95ed-ade78f1e1afd"}, {"title": "李克用大举蕃汉兵南下，表请讨三帅", "start_year": 895, "end_year": 895, "time_original": "895年七月朔到河中以前；确日未载", "dynasty": "唐", "description": "李克用大举蕃汉兵南下，上表指王行瑜、李茂贞、韩建称兵犯阙、杀害大臣，请求讨伐。", "phases": [], "location_name": "河东、关中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2d8fc679-656c-5083-92e4-3e51653f0947"}, {"title": "李克用移檄三镇，三帅惧", "start_year": 895, "end_year": 895, "time_original": "895年南下时；确日未载", "dynasty": "唐", "description": "李克用向三镇发檄，王行瑜等大惧。", "phases": [], "location_name": "三镇", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e3fb8aba-9cac-5ee1-b4ab-78856d3ddd18"}, {"title": "王瑶闭城拒李克用，绛州旬日被克", "start_year": 895, "end_year": 895, "time_original": "895年南下途中；攻城旬日，确日未载", "dynasty": "唐", "description": "李克用军到绛州，刺史王瑶闭城抵拒。李克用进攻，十日后攻下。", "phases": [], "location_name": "绛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9af407bc-8ff9-50d9-a717-90fb20ec4af9"}, {"title": "李克用斩王瑶，杀城中违拒者千余", "start_year": 895, "end_year": 895, "time_original": "895年绛州攻克后；确日未载", "dynasty": "唐", "description": "李克用在军门斩王瑶，并杀城中抵拒者一千余人。", "phases": [], "location_name": "绛州、军门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb47a744-7859-5491-af6f-3b569d6c0a53"}, {"title": "李克用至河中，王珂迎谒", "start_year": 895, "end_year": 895, "time_original": "895年秋七月丙辰朔", "dynasty": "唐", "description": "李克用到河中，王珂在路迎谒。", "phases": [], "location_name": "河中、路", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aff5bb5a-c736-52a9-8ebe-cea18d281279"}, {"title": "王行约败于朝邑", "start_year": 895, "end_year": 895, "time_original": "895年七月戊午以前；确日未載", "dynasty": "唐", "description": "匡国节度使王行约在朝邑战败。", "phases": [], "location_name": "朝邑", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "64fadc60-1d14-5d23-8d42-e408595fb744"}, {"title": "王行约弃同州逃京师", "start_year": 895, "end_year": 895, "time_original": "895年七月戊午弃城；己未至京", "dynasty": "唐", "description": "王行约戊午弃同州逃走，己未到京师。", "phases": [], "location_name": "同州、京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "09b105df-2a60-56af-82b2-e7cff8227713"}, {"title": "王行实与王行约率众掠西市", "start_year": 895, "end_year": 895, "time_original": "895年七月王行约至京以后；确日未另载", "dynasty": "唐", "description": "王行约之弟、左军指挥使王行实率众与王行约大掠西市。", "phases": [], "location_name": "京师、西市", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5f860783-4d2f-5df4-8b54-b74abe3b82eb"}, {"title": "王行实奏称同华已没，请帝幸邠州", "start_year": 895, "end_year": 895, "time_original": "895年七月王氏掠西市后；确日未载", "dynasty": "唐", "description": "王行实上奏称同州、华州已经失守、沙陀将到，请皇帝去邠州。", "phases": [], "location_name": "京师、邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aeb8ebcd-b3a4-592a-adc7-f683a4b31c37"}, {"title": "骆全瓘请帝幸凤翔", "start_year": 895, "end_year": 895, "time_original": "895年七月庚申", "dynasty": "唐", "description": "枢密使骆全瓘上奏请皇帝去凤翔。", "phases": [], "location_name": "京师、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7ab67d2-11c0-5664-a711-9663f86e6ad9"}, {"title": "唐昭宗称李克用尚在河中，令各抚本军", "start_year": 895, "end_year": 895, "time_original": "895年七月庚申条", "dynasty": "唐", "description": "唐昭宗称已收到李克用表，其军尚驻河中，即使沙陀到来也自有应对；令诸臣安抚本军，不得摇动。", "phases": [], "location_name": "京师、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "98bb9102-4e0a-5437-9927-76be2e801db8"}, {"title": "李继鹏骆全瓘谋劫帝去凤翔", "start_year": 895, "end_year": 895, "time_original": "895年七月京师乱前；确日未另载", "dynasty": "唐", "description": "右军指挥使李继鹏与骆全瓘谋劫皇帝去凤翔。", "phases": [], "location_name": "京师、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8156fd35-f6ad-585f-81c5-5f2678db2428"}, {"title": "刘景宣王行实欲劫帝去邠州", "start_year": 895, "end_year": 895, "time_original": "895年七月知右军谋劫以后；确日未另载", "dynasty": "唐", "description": "中尉刘景宣与王行实得知右军计划后，欲劫皇帝去邠州。", "phases": [], "location_name": "京师、邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "96865037-89d6-5e49-a98c-c5c8e17c4335"}, {"title": "孔纬面折刘景宣，不可轻离宫阙", "start_year": 895, "end_year": 895, "time_original": "895年七月京师乱前；确日未另载", "dynasty": "唐", "description": "